/* @lc app=leetcode id=1801 lang=kotlin */
class Solution { fun getNumberOfBacklogOrders(orders: Array<IntArray>): Int = orders.fold(java.util.PriorityQueue<IntArray>({ a, b -> b[0] - a[0] }) to java.util.PriorityQueue<IntArray>({ a, b -> a[0] - b[0] })) { (buy, sell), o -> o.also { if (o[2] == 0) generateSequence { if (o[1] > 0 && sell.isNotEmpty() && sell.peek()[0] <= o[0]) sell.poll() else null }.forEach { c -> minOf(o[1], c[1]).let { m -> o[1].also { o[1] -= m }.also { c[1] -= m }.also { if (c[1] > 0) sell.offer(c) } } }.also { if (o[1] > 0) buy.offer(intArrayOf(o[0], o[1])) } else generateSequence { if (o[1] > 0 && buy.isNotEmpty() && buy.peek()[0] >= o[0]) buy.poll() else null }.forEach { c -> minOf(o[1], c[1]).let { m -> o[1].also { o[1] -= m }.also { c[1] -= m }.also { if (c[1] > 0) buy.offer(c) } } }.also { if (o[1] > 0) sell.offer(intArrayOf(o[0], o[1])) } }.let { buy to sell } }.run { (first.sumOf { it[1].toLong() } + second.sumOf { it[1].toLong() }) % 1000000007 }.toInt() }